function setup(){
  createCanvas(600, 400);
  reset();
}
function draw(){
  for(let m=0;m<100000;m++){
    // create onehundredthousand random points
    let a = floor(random(1,width));
    let b = floor(random(1,height));
    if(red(window.color(get(a,b)))!=0){// if pixel is black
      let c = floor(random(0,4));// one of 4 directions
      let d = 0;// an x offset for direction
      let e = 0;// an y offset for direction
      switch(c){// assign x and y offsets
        case 0:
        d=1;
        e=0;
        break;
        case 1:
        d=0;
        e=1;
        break;
        case 2:
        d=-1;
        e=0;
        break;
        case 3:
        d=0;
        e=-1;
        break;
      }
      if((a+d>0)&&(b+e>0)&&
         (a+d<width-1)&&(b+e<height-1)&&
         // i was worried about the domain of get() or set()
         // it will not throw an "index out of bounds" anyway
       red(window.color(get(a+d,b+e)))==0){// if the target is black
        let ram = 10;// makes the let change
        let clr = get(a,b);//
        let re = int(constrain(red(window.color(clr))+random(-ram,ram),1,255));
        let gr = int(constrain(green(window.color(clr))+random(-ram,ram),1,255));
        let bu = int(constrain(blue(window.color(clr))+random(-ram,ram),1,255));
        set(a+d,b+e,color(re,gr,bu));
      }
    }
  }
}
function keyPressed(){
  if(key==' '){
    reset();
//    save("evolution.bmp");
  }
}
function reset(){
  background(0);
  let edge = 1;// distance from inner to outer circle
  let diam = width/2;
  noFill();
  ellipseMode(CENTER);
  stroke("#8800FF");// blue
  ellipse(width/2,height/2,diam-edge,diam-edge);
  stroke("#FF8800");// orange
  ellipse(width/2,height/2,diam+edge,diam+edge);
//  set(width/2,height/2,color(255));
}
